int binarySearchBoundaries(vector<int>& arr, int target) {
    int low = 0, high = arr.size() - 1;
    int ans = -1; // Or return n or default value depending on problem

    while (low <= high) {
        int mid = low + (high - low) / 2;
        // Check condition (e.g., arr[mid] >= target for Lower Bound)
        if (condition(arr[mid])) {
            ans = mid;         // Record the potential candidate
            high = mid - 1;    // Search left half to find an earlier transition
        } else {
            low = mid + 1;     // Search right half
        }
    }
    return ans;
}

int searchRotated(vector<int>& nums, int target) {
    int low = 0, high = nums.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (nums[mid] == target) return mid;
        if (nums[low] <= nums[mid]) { // Left half is sorted
            if (nums[low] <= target && target < nums[mid]) high = mid - 1;
            else low = mid + 1;
        } else { // Right half is sorted
            if (nums[mid] < target && target <= nums[high]) low = mid + 1;
            else high = mid - 1;
        }
    }
    return -1;
}

int findPeak(vector<int>& arr) {
    int low = 0, high = arr.size() - 1;
    while (low < high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] > arr[mid + 1]) {
            high = mid;      // Peak lies on the left side (inclusive of mid)
        } else {
            low = mid + 1;   // Peak lies strictly on the right side
        }
    }
    return low;
}

